import{c as e,Q as a,j as l,m as d}from"./chunks/framework.3U2mntTB.js";const y=JSON.parse('{"title":"Commands & Permissions","description":"","frontmatter":{},"headers":[],"relativePath":"configuration/commands-permissions.md","filePath":"configuration/commands-permissions.md"}'),s={name:"configuration/commands-permissions.md"};function o(n,t,i,r,c,h){return a(),l("div",null,[...t[0]||(t[0]=[d('<h1 id="commands-permissions" tabindex="-1">Commands &amp; Permissions <a class="header-anchor" href="#commands-permissions" aria-label="Permalink to &quot;Commands &amp; Permissions&quot;">​</a></h1><p>Below is a list of commands and their associated permissions for AetherUHC.</p><h2 id="host-commands" tabindex="-1">Host Commands <a class="header-anchor" href="#host-commands" aria-label="Permalink to &quot;Host Commands&quot;">​</a></h2><p>These commands require the <code>aetheruhc.host</code> permission and are used to configure and run the match.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Command</th><th style="text-align:left;">Description</th><th style="text-align:left;">Permission</th></tr></thead><tbody><tr><td style="text-align:left;"><code>/host</code></td><td style="text-align:left;">Opens the main Host configuration GUI.</td><td style="text-align:left;"><code>aetheruhc.host</code></td></tr><tr><td style="text-align:left;"><code>/scenarios</code></td><td style="text-align:left;">Opens the Scenarios manager GUI.</td><td style="text-align:left;"><code>aetheruhc.host</code></td></tr><tr><td style="text-align:left;"><code>/start</code></td><td style="text-align:left;">Starts the UHC match (if configured).</td><td style="text-align:left;"><code>aetheruhc.host</code></td></tr><tr><td style="text-align:left;"><code>/heal &lt;player&gt;</code></td><td style="text-align:left;">Heals a specific player or all players.</td><td style="text-align:left;"><code>aetheruhc.host</code></td></tr><tr><td style="text-align:left;"><code>/feed &lt;player&gt;</code></td><td style="text-align:left;">Feeds a specific player or all players.</td><td style="text-align:left;"><code>aetheruhc.host</code></td></tr><tr><td style="text-align:left;"><code>/revive &lt;player&gt;</code></td><td style="text-align:left;">Revives a dead player and teleports them to their death location.</td><td style="text-align:left;"><code>aetheruhc.host</code></td></tr></tbody></table><h2 id="player-commands" tabindex="-1">Player Commands <a class="header-anchor" href="#player-commands" aria-label="Permalink to &quot;Player Commands&quot;">​</a></h2><p>These commands are available to all players by default.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Command</th><th style="text-align:left;">Description</th><th style="text-align:left;">Permission</th></tr></thead><tbody><tr><td style="text-align:left;"><code>/helpop &lt;msg&gt;</code></td><td style="text-align:left;">Sends a message to online moderators/hosts.</td><td style="text-align:left;">None</td></tr><tr><td style="text-align:left;"><code>/scenarios</code></td><td style="text-align:left;">View the currently active scenarios (read-only for players).</td><td style="text-align:left;">None</td></tr><tr><td style="text-align:left;"><code>/stats</code></td><td style="text-align:left;">View your all-time UHC statistics.</td><td style="text-align:left;">None</td></tr><tr><td style="text-align:left;"><code>/leaderboard</code></td><td style="text-align:left;">View the top players on the server.</td><td style="text-align:left;">None</td></tr><tr><td style="text-align:left;"><code>/rules</code></td><td style="text-align:left;">Read the match rules.</td><td style="text-align:left;">None</td></tr><tr><td style="text-align:left;"><code>/ping</code></td><td style="text-align:left;">Check your connection latency to the server.</td><td style="text-align:left;">None</td></tr></tbody></table><h2 id="admin-commands" tabindex="-1">Admin Commands <a class="header-anchor" href="#admin-commands" aria-label="Permalink to &quot;Admin Commands&quot;">​</a></h2><p>These commands are strictly for server administrators managing the world/plugin.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Command</th><th style="text-align:left;">Description</th><th style="text-align:left;">Permission</th></tr></thead><tbody><tr><td style="text-align:left;"><code>/aetheruhc reload</code></td><td style="text-align:left;">Reloads the configuration and language files.</td><td style="text-align:left;"><code>aetheruhc.admin</code></td></tr><tr><td style="text-align:left;"><code>/aetheruhc setlobby</code></td><td style="text-align:left;">Sets the central lobby spawn location.</td><td style="text-align:left;"><code>aetheruhc.admin</code></td></tr></tbody></table>',11)])])}const f=e(s,[["render",o]]);export{y as __pageData,f as default};
